pub const FINGERPRINT: [u8; 8] = 0x61f1085bd11529d0u64.to_be_bytes();
pub const TYPE_NAME: &str = "nuwax_msgs.RecentCloud3D";
pub const DEFAULT_TOPIC: &str = "/nav/observations3d";
pub const MAX_BYTES: usize = 2 * 1024 * 1024;

/// 同一帧注册时冻结的真实传感器原点与机体姿态。身份和时间由 cloud 唯一承载。
/// body_orientation_xyzw 不是传感器四元数；world 点不得再次用此姿态变换。
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct RegisteredCloudPose {
    /// 同帧真实雷达原点，单位为米。
    pub sensor_origin_map: [f64; 3],
    /// 同帧冻结 map_from_body 的机体位置，单位为米。
    pub body_position_map: [f64; 3],
    /// 同帧冻结机体姿态，单位四元数，按 xyzw 排列。
    pub body_orientation_xyzw: [f64; 4],
    /// 与该帧配对的原始里程计时间。
    pub paired_odometry_timestamp_ns: i64,
}
impl RegisteredCloudPose {
    /// 验证有限坐标、机体单位四元数及配对时间。
    pub fn validate(&self) -> CodecResult<()> {
        if self.paired_odometry_timestamp_ns <= 0 {
            return Err(bad("registered cloud requires an odometry timestamp"));
        }
        if self
            .sensor_origin_map
            .iter()
            .chain(self.body_position_map.iter())
            .chain(self.body_orientation_xyzw.iter())
            .any(|value| !value.is_finite())
        {
            return Err(bad("registered cloud pose must contain only finite values"));
        }
        let norm_squared: f64 = self
            .body_orientation_xyzw
            .iter()
            .map(|value| value * value)
            .sum();
        if (norm_squared - 1.0).abs() > 1e-6 {
            return Err(bad("registered cloud body quaternion must be normalized"));
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct RecentCloud3D {
    pub session_id: String,
    pub sequence: i64,
    /// 空点云撤销近期观测，不清空持久地图。
    pub cloud: Option<PointCloud2>,
    /// None 保留原点未知；禁止补零或使用最新位姿替代同帧配对。
    pub registration: Option<RegisteredCloudPose>,
    /// Sorted original emitted-point indices fitted to physical layer candidates.
    /// These are not an unconditional obstacle exclusion: consumers must match
    /// the selected persistent contact layer before granting a contact exception.
    pub ground_point_indices: Vec<u32>,
}
fn bad(message: &str) -> CodecError {
    CodecError::LcmDecode(message.into())
}
fn validate_identity(session: &str, sequence: i64) -> CodecResult<()> {
    if sequence <= 0 || session.is_empty() || session.len() > 1024
        || session.trim() != session || session.chars().any(char::is_control)
    {
        return Err(bad("invalid recent cloud session or sequence"));
    }
    Ok(())
}

fn validate_members(cloud: Option<&PointCloud2>, members: &[u32]) -> CodecResult<()> {
    let count = cloud.map_or(0, |points| i64::from(points.width) * i64::from(points.height));
    if members.len() > lio::MAX_LIO_EMITTED_POINT_COUNT as usize
        || members.windows(2).any(|pair| pair[0] >= pair[1])
        || members.last().is_some_and(|last| i64::from(*last) >= count)
    {
        return Err(bad("invalid recent cloud ground indices"));
    }
    Ok(())
}

fn validate_cloud(cloud: &PointCloud2) -> CodecResult<()> {
    if cloud.header.frame_id.is_empty() || cloud.header.stamp_sec < 0
        || (cloud.header.stamp_sec == 0 && cloud.header.stamp_nsec == 0)
        || !(0..1_000_000_000).contains(&cloud.header.stamp_nsec)
        || i64::from(cloud.width) * i64::from(cloud.height) > lio::MAX_LIO_EMITTED_POINT_COUNT
    {
        return Err(bad("invalid recent cloud frame, source time or point count"));
    }
    schema::validate_navigation_map_3d_cloud(cloud, false).map_err(CodecError::LcmDecode)
}

fn validate_registration(
    cloud: Option<&PointCloud2>,
    registration: Option<&RegisteredCloudPose>,
) -> CodecResult<()> {
    if let Some(registration) = registration {
        if cloud.is_none() {
            return Err(bad("revoked cloud must not contain a registration pose"));
        }
        registration.validate()?;
    }
    Ok(())
}

impl RecentCloud3D {
    pub fn validate(&self) -> CodecResult<()> {
        validate(self.session_id.as_str(), self.sequence, self.cloud.as_ref(),
            self.registration.as_ref(), &self.ground_point_indices)
    }
}

fn validate(
    session: &str,
    sequence: i64,
    cloud: Option<&PointCloud2>,
    registration: Option<&RegisteredCloudPose>,
    members: &[u32],
) -> CodecResult<()> {
    validate_identity(session, sequence)?;
    validate_members(cloud, members)?;
    validate_registration(cloud, registration)?;
    if let Some(cloud) = cloud {
        validate_cloud(cloud)?;
    }
    Ok(())
}

pub fn encode_body(value: &RecentCloud3D) -> CodecResult<Vec<u8>> {
    encode_borrowed(&value.session_id, value.sequence, value.cloud.as_ref(),
        value.registration.as_ref(), &value.ground_point_indices)
}

/// 借用单帧点云，在编码边界保持原始点和地面成员的顺序。
pub fn encode_borrowed(
    session: &str,
    sequence: i64,
    cloud: Option<&PointCloud2>,
    registration: Option<&RegisteredCloudPose>,
    members: &[u32],
) -> CodecResult<Vec<u8>> {
    validate(session, sequence, cloud, registration, members)?;
    let payload_capacity = cloud.map_or(0, |cloud| cloud.data.len() + 256);
    let mut out = Vec::with_capacity(112 + session.len() + members.len() * 4 + payload_capacity);
    out.extend(((session.len() + 1) as i32).to_be_bytes());
    out.extend(session.as_bytes());
    out.push(0);
    out.extend(sequence.to_be_bytes());
    out.push(u8::from(cloud.is_none()));
    out.extend(i32::from(registration.is_some()).to_be_bytes());
    if let Some(registration) = registration {
        for value in registration.sensor_origin_map.iter()
            .chain(&registration.body_position_map).chain(&registration.body_orientation_xyzw)
        {
            out.extend(value.to_be_bytes());
        }
        out.extend(registration.paired_odometry_timestamp_ns.to_be_bytes());
    }
    out.extend((members.len() as i32).to_be_bytes());
    for member in members {
        out.extend((*member as i32).to_be_bytes());
    }
    out.extend(schema::encode_point_cloud2_body(cloud.unwrap_or(&PointCloud2::default()))?);
    if out.len() > MAX_BYTES {
        return Err(bad("recent cloud exceeds wire budget"));
    }
    Ok(out)
}

pub fn decode_body(input: &[u8]) -> CodecResult<RecentCloud3D> {
    if input.len() > MAX_BYTES {
        return Err(bad("recent cloud exceeds wire budget"));
    }
    let mut reader = Reader { input, pos: 0 };
    let len = reader.i32()?;
    if !(2..=1025).contains(&len) {
        return Err(bad("recent cloud session length invalid"));
    }
    let session = reader.take(len as usize)?;
    if session.last() != Some(&0) {
        return Err(bad("recent cloud session lacks terminator"));
    }
    let session_id = std::str::from_utf8(&session[..session.len() - 1])
        .map_err(|_| bad("invalid session UTF-8"))?.to_owned();
    let sequence = reader.i64()?;
    let cleared = match reader.take(1)?[0] {
        0 => false,
        1 => true,
        _ => return Err(bad("invalid recent cloud revoke flag")),
    };
    let registration = match reader.i32()? {
        0 => None,
        1 => Some(RegisteredCloudPose {
            sensor_origin_map: reader.f64_array()?,
            body_position_map: reader.f64_array()?,
            body_orientation_xyzw: reader.f64_array()?,
            paired_odometry_timestamp_ns: reader.i64()?,
        }),
        _ => return Err(bad("recent cloud registration count must be zero or one")),
    };
    let count = reader.i32()?;
    if count < 0 || i64::from(count) > lio::MAX_LIO_EMITTED_POINT_COUNT {
        return Err(bad("recent cloud ground count exceeds budget"));
    }
    let mut ground_point_indices = Vec::with_capacity(count as usize);
    for _ in 0..count {
        ground_point_indices.push(u32::try_from(reader.i32()?)
            .map_err(|_| bad("negative ground point index"))?);
    }
    let cloud = schema::decode_point_cloud2_body(&input[reader.pos..])?;
    if cleared && cloud != PointCloud2::default() {
        return Err(bad("revoked recent cloud must be empty"));
    }
    let packet = RecentCloud3D {
        session_id, sequence, cloud: (!cleared).then_some(cloud),
        registration, ground_point_indices,
    };
    packet.validate()?;
    Ok(packet)
}
struct Reader<'a> {
    input: &'a [u8],
    pos: usize,
}
impl<'a> Reader<'a> {
    fn take(&mut self, count: usize) -> CodecResult<&'a [u8]> {
        let end = self
            .pos
            .checked_add(count)
            .filter(|end| *end <= self.input.len())
            .ok_or_else(|| bad("truncated recent cloud"))?;
        let value = &self.input[self.pos..end];
        self.pos = end;
        Ok(value)
    }
    fn f64_array<const N: usize>(&mut self) -> CodecResult<[f64; N]> {
        let mut result = [0.0; N];
        for value in &mut result {
            *value = f64::from_be_bytes(self.take(8)?.try_into().unwrap());
        }
        Ok(result)
    }
    fn i32(&mut self) -> CodecResult<i32> {
        Ok(i32::from_be_bytes(self.take(4)?.try_into().unwrap()))
    }
    fn i64(&mut self) -> CodecResult<i64> {
        Ok(i64::from_be_bytes(self.take(8)?.try_into().unwrap()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn explicit_revocation_roundtrips_and_rejects_fake_data() {
        let value = RecentCloud3D {
            session_id: "map-owner".into(),
            sequence: 1,
            cloud: None,
            registration: None,
            ground_point_indices: vec![],
        };
        let bytes = encode_body(&value).unwrap();
        assert_eq!(decode_body(&bytes).unwrap(), value);
        for n in 0..bytes.len() {
            assert!(decode_body(&bytes[..n]).is_err());
        }
        let mut trailing = bytes.clone();
        trailing.push(0);
        assert!(decode_body(&trailing).is_err());
        let mut bad = value.clone();
        bad.ground_point_indices = vec![0];
        assert!(encode_body(&bad).is_err());
        let mut bad = value;
        bad.sequence = 0;
        assert!(encode_body(&bad).is_err());
    }
    fn live() -> RecentCloud3D {
        use super::super::schema::{Header, PointCloud2, PointField};
        let cloud = PointCloud2 {
            header: Header {
                seq: 7,
                stamp_sec: 1,
                stamp_nsec: 0,
                frame_id: "map".into(),
            },
            height: 1,
            width: 2,
            fields: ["x", "y", "z"]
                .iter()
                .enumerate()
                .map(|(i, name)| PointField {
                    name: (*name).into(),
                    offset: (i * 4) as i32,
                    datatype: 7,
                    count: 1,
                })
                .collect(),
            point_step: 12,
            row_step: 24,
            data: [0.01_f32, 0.02, 0.03, 0.01, 0.02, 0.4]
                .into_iter()
                .flat_map(f32::to_le_bytes)
                .collect(),
            is_dense: true,
            ..Default::default()
        };
        RecentCloud3D {
            session_id: "ground-owner".into(),
            ground_point_indices: vec![0],
            registration: Some(RegisteredCloudPose {
                sensor_origin_map: [12.5, -3.25, 0.75],
                body_position_map: [12.0, -3.0, 0.5],
                body_orientation_xyzw: [0.0, 0.0, 0.6, 0.8],
                paired_odometry_timestamp_ns: 999_999_999,
            }),
            sequence: 7,
            cloud: Some(cloud),
        }
    }
    #[test]
    fn admitted_points_and_ground_indices_roundtrip_without_changing_source_time() {
        let value = live();
        let bytes = encode_body(&value).unwrap();
        assert_eq!(decode_body(&bytes).unwrap(), value);
        for length in 0..bytes.len() {
            assert!(decode_body(&bytes[..length]).is_err());
        }
        let mut trailing = bytes.clone();
        trailing.push(0);
        assert!(decode_body(&trailing).is_err());
        for indices in [vec![0, 0], vec![1, 0], vec![2], vec![u32::MAX]] {
            let mut invalid = value.clone();
            invalid.ground_point_indices = indices;
            assert!(encode_body(&invalid).is_err());
        }
        let mut invalid = value;
        invalid.cloud.as_mut().unwrap().header.frame_id.clear();
        assert!(encode_body(&invalid).is_err());
    }
    #[test]
    fn registered_world_points_and_paired_source_identity_remain_unchanged() {
        let mut value = live();
        value.registration.as_mut().unwrap().paired_odometry_timestamp_ns = 999_999_900;
        let decoded = decode_body(&encode_body(&value).unwrap()).unwrap();
        assert_eq!(decoded.cloud, value.cloud);
        assert_eq!(decoded.registration, value.registration);
        assert_eq!(
            decoded.cloud.as_ref().unwrap().data,
            value.cloud.as_ref().unwrap().data
        );
        assert_eq!(
            decoded.cloud.as_ref().unwrap().width,
            2,
            "ground 标签不能移除点"
        );
    }

    #[test]
    fn unknown_registration_remains_none_and_revocation_cannot_smuggle_a_pose() {
        let mut value = live();
        value.registration = None;
        assert_eq!(decode_body(&encode_body(&value).unwrap()).unwrap(), value);
        let mut revoked = live();
        revoked.cloud = None;
        revoked.ground_point_indices.clear();
        assert!(revoked.validate().is_err());
        assert!(encode_body(&revoked).is_err());
        let mut encoded = encode_body(&live()).unwrap();
        // 严格禁止携带 payload 或 registration 的撤销消息。
        encoded[cleared_offset(&live())] = 1;
        assert!(decode_body(&encoded).is_err());
    }

    fn cleared_offset(value: &RecentCloud3D) -> usize {
        4 + value.session_id.len() + 1 + 8
    }

    #[test]
    fn nonfinite_registration_and_nonunit_body_quaternion_reject_on_both_sides() {
        let value = live();
        let registration_start = cleared_offset(&value) + 1 + 4;
        for (index, invalid) in [
            (0, f64::NAN),
            (2, f64::INFINITY),
            (3, f64::NEG_INFINITY),
            (6, f64::NAN),
            (9, 0.0),
            (9, 2.0),
        ] {
            let mut wire = encode_body(&value).unwrap();
            wire[registration_start + index * 8..registration_start + (index + 1) * 8]
                .copy_from_slice(&invalid.to_be_bytes());
            assert!(decode_body(&wire).is_err(), "invalid pose index={index}");
            let mut bad = value.clone();
            let pose = bad.registration.as_mut().unwrap();
            match index {
                0..=2 => pose.sensor_origin_map[index] = invalid,
                3..=5 => pose.body_position_map[index - 3] = invalid,
                _ => pose.body_orientation_xyzw[index - 6] = invalid,
            }
            assert!(bad.validate().is_err());
            assert!(encode_body(&bad).is_err());
        }
        let mut invalid = value;
        invalid.registration.as_mut().unwrap().body_orientation_xyzw = [0.0; 4];
        assert!(encode_body(&invalid).is_err());
    }

    #[test]
    fn nonfinite_world_coordinates_reject_without_filtering_or_transforming() {
        for bad_coordinate in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            let mut value = live();
            let cloud = value.cloud.as_mut().unwrap();
            cloud.data[0..4].copy_from_slice(&bad_coordinate.to_le_bytes());
            assert!(value.validate().is_err());
            assert!(encode_body(&value).is_err());
            let mut valid = live();
            // 直接替换末尾完整嵌套包，模拟外部生成绑定送入的非法坐标。
            let invalid_nested =
                schema::encode_point_cloud2_body(value.cloud.as_ref().unwrap()).unwrap();
            let mut wire = encode_body(&valid).unwrap();
            let start = wire.len() - invalid_nested.len();
            wire[start..].copy_from_slice(&invalid_nested);
            assert!(decode_body(&wire).is_err());
            valid.cloud.as_mut().unwrap().is_bigendian = true;
            valid.cloud.as_mut().unwrap().data = [0.01_f32, 0.02, 0.03, 0.01, 0.02, 0.4]
                .into_iter()
                .flat_map(f32::to_be_bytes)
                .collect();
            assert_eq!(decode_body(&encode_body(&valid).unwrap()).unwrap(), valid);
        }
    }

    #[test]
    fn rejects_invalid_session_registration_count_and_wire_budget_overflow() {
        let value = live();
        let mut wire = encode_body(&value).unwrap();
        wire[..4].copy_from_slice(&1_i32.to_be_bytes());
        assert!(decode_body(&wire).is_err());
        for invalid in [-1_i32, 2, i32::MAX] {
            let mut wire = encode_body(&value).unwrap();
            let count = cleared_offset(&value) + 1;
            wire[count..count + 4].copy_from_slice(&invalid.to_be_bytes());
            assert!(decode_body(&wire).is_err());
        }
        assert!(decode_body(&vec![0; MAX_BYTES + 1]).is_err());
        assert_eq!(crate::lcm::compute_hash(TYPE_NAME), FINGERPRINT);
        assert_ne!(FINGERPRINT, 0xfefc4448c3229419_u64.to_be_bytes());
    }

    #[test]
    #[ignore = "release codec allocation/copy timing diagnostic"]
    fn recent_nested_cloud_decode_cost() {
        let mut value = live();
        let cloud = value.cloud.as_mut().unwrap();
        cloud.width = 100_000;
        cloud.row_step = cloud.width * cloud.point_step;
        cloud.data = vec![0; cloud.row_step as usize];
        let data_bytes = cloud.data.len();
        let wire = encode_body(&value).unwrap();
        assert_eq!(decode_body(&wire).unwrap(), value);
        let iterations = 2_000;
        let start = std::time::Instant::now();
        for _ in 0..iterations {
            std::hint::black_box(decode_body(std::hint::black_box(&wire)).unwrap());
        }
        eprintln!(
            "recent_nested_cloud iterations={iterations} data_bytes={data_bytes} elapsed_ms={:.3}",
            start.elapsed().as_secs_f64() * 1000.0
        );
    }

    #[test]
    fn generated_python_decodes_and_reencodes_the_exact_live_packet() {
        use std::io::Write;
        use std::process::{Command, Stdio};
        let value = live();
        let mut full = FINGERPRINT.to_vec();
        full.extend(encode_body(&value).unwrap());
        let mut child = Command::new("python3")
            .arg("-c")
            .arg(
                r#"
import sys
from nuwax_msgs.RecentCloud3D import RecentCloud3D
raw=sys.stdin.buffer.read()
value=RecentCloud3D.decode(raw)
assert value.sequence==7 and value.session_id=='ground-owner'
assert list(value.ground_point_indices)==[0]
assert value.registration_count==1
assert list(value.registration[0].sensor_origin_map)==[12.5,-3.25,0.75]
assert list(value.registration[0].body_position_map)==[12.0,-3.0,0.5]
assert list(value.registration[0].body_orientation_xyzw)==[0.0,0.0,0.6,0.8]
assert value.registration[0].paired_odometry_timestamp_ns==999999999
assert value.cloud.header.stamp.sec==1 and value.cloud.width==2
assert value.encode()==raw
try:
    RecentCloud3D.decode(bytes.fromhex('fefc4448c3229419') + raw[8:])
    raise AssertionError('v1 fingerprint accepted')
except ValueError:
    pass
sys.stdout.buffer.write(value.encode())
"#,
            )
            .env(
                "PYTHONPATH",
                std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                    .join("../../lcmtypes/generated/python"),
            )
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("Python codec verifier");
        child.stdin.take().unwrap().write_all(&full).unwrap();
        let result = child.wait_with_output().unwrap();
        assert!(
            result.status.success(),
            "{}",
            String::from_utf8_lossy(&result.stderr)
        );
        assert_eq!(result.stdout, full);
        assert_eq!(decode_body(&result.stdout[8..]).unwrap(), value);
    }
}
